mapper.select:
SELECT s.stock_code, s.stock_name, s.market_type, sp.price_date, sp.open_price, sp.close_price, sp.high_price, sp.low_price, sp.volume FROM stock_price as sp JOIN stock as s on sp.stock_code = s.stock_code WHERE sp.stock_code = #{stockCode}
AND sp.price_date >= #{startDate}
AND sp.price_date <= #{endDate}
ORDER BY sp.price_date ASC
